import { readFile, stat } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

import type { HmrContext, ModuleNode, Plugin, ResolvedConfig } from 'vite'
import { normalizePath } from 'vite'

export type FeatureFlagValue = boolean | number | string | null

export interface FeatureFlagsSchema extends Record<string, FeatureFlagValue> {}

type KnownFeatureFlagName = Extract<keyof FeatureFlagsSchema, string>
type FeatureFlagNameList = [KnownFeatureFlagName] extends [never]
  ? readonly string[]
  : readonly KnownFeatureFlagName[]

export type FeatureFlags = Readonly<
  [KnownFeatureFlagName] extends [never]
    ? Record<string, FeatureFlagValue>
    : FeatureFlagsSchema
>

export interface FeatureFlagsOptions {
  source: string | URL
  expose: FeatureFlagNameList
}

interface FileSignature {
  mtimeMs: number
  size: number
}

interface LoadedFlags {
  sourcePath: string
  flags: Record<string, FeatureFlagValue>
}

interface CacheEntry extends LoadedFlags {
  signature: FileSignature
}

const PLUGIN_NAME = 'feature-flags'
const VIRTUAL_MODULE_ID = 'virtual:feature-flags'
const RESOLVED_VIRTUAL_MODULE_ID = `\0${VIRTUAL_MODULE_ID}`

export function featureFlags(options: FeatureFlagsOptions): Plugin {
  let config: ResolvedConfig | undefined
  let resolvedSourcePath: string | undefined
  let cache: CacheEntry | undefined

  const clearCache = () => {
    cache = undefined
  }

  const getConfigRoot = () => config?.root ?? process.cwd()

  const ensureSourcePath = () => {
    if (resolvedSourcePath) {
      return resolvedSourcePath
    }

    resolvedSourcePath = resolveSourcePath(options.source, getConfigRoot())
    return resolvedSourcePath
  }

  const readPublicFlags = async (): Promise<LoadedFlags> => {
    const sourcePath = ensureSourcePath()
    const signature = await getFileSignature(sourcePath)

    if (cache && isSameSignature(cache.signature, signature)) {
      return cache
    }

    const fileContents = await readSourceFile(sourcePath)
    const parsed = parseFlagDocument(fileContents, sourcePath)
    const flags = pickExposedFlags(parsed, options.expose, sourcePath)

    cache = {
      sourcePath,
      flags,
      signature,
    }

    return cache
  }

  const invalidateVirtualModule = (server: HmrContext['server']) => {
    const virtualModule = server.moduleGraph.getModuleById(RESOLVED_VIRTUAL_MODULE_ID)
    if (!virtualModule) {
      return []
    }

    const affected = new Set<ModuleNode>([virtualModule])
    collectImporters(virtualModule, affected)

    for (const moduleNode of affected) {
      server.moduleGraph.invalidateModule(
        moduleNode,
        undefined,
        undefined,
        true,
      )
    }

    return [...affected]
  }

  return {
    name: PLUGIN_NAME,
    enforce: 'pre',
    configResolved(resolvedConfig) {
      config = resolvedConfig
      clearCache()
    },
    buildStart() {
      const exposedKeys = [...options.expose]
      if (exposedKeys.length === 0) {
        throw createDiagnostic(
          'EMPTY_EXPOSE',
          'The `expose` option must include at least one public flag key.',
          [`Update the Vite config for ${PLUGIN_NAME} to expose the public flags consumed by the client.`],
        )
      }
    },
    resolveId(id) {
      if (id === VIRTUAL_MODULE_ID) {
        return RESOLVED_VIRTUAL_MODULE_ID
      }

      return null
    },
    async load(id) {
      if (id !== RESOLVED_VIRTUAL_MODULE_ID) {
        return null
      }

      const loadedFlags = await readPublicFlags()
      this.addWatchFile(loadedFlags.sourcePath)

      return {
        code: renderVirtualModule(loadedFlags.flags),
        map: createSourceMap(loadedFlags.sourcePath),
      }
    },
    handleHotUpdate(context) {
      const sourcePath = ensureSourcePath()
      if (normalizePath(context.file) !== sourcePath) {
        return
      }

      clearCache()
      return invalidateVirtualModule(context.server)
    },
  }
}

function resolveSourcePath(source: string | URL, configRoot: string) {
  if (source instanceof URL) {
    if (source.protocol !== 'file:') {
      throw createDiagnostic(
        'UNSUPPORTED_SOURCE_URL',
        `Expected a file URL for \`source\`, received ${source.href}.`,
        ['Use a file URL such as `new URL("./flags.json", import.meta.url)` or pass an absolute/relative file path.'],
      )
    }

    return normalizePath(fileURLToPath(source))
  }

  return normalizePath(new URL(source, `file://${normalizePath(configRoot)}/`).pathname)
}

async function getFileSignature(sourcePath: string): Promise<FileSignature> {
  try {
    const metadata = await stat(sourcePath)
    return {
      mtimeMs: metadata.mtimeMs,
      size: metadata.size,
    }
  } catch (error) {
    throw createDiagnostic(
      'SOURCE_NOT_FOUND',
      `Unable to read feature flags from ${sourcePath}.`,
      ['Create the JSON file or update the `source` option to point at the correct file.'],
      error,
    )
  }
}

function isSameSignature(left: FileSignature, right: FileSignature) {
  return left.mtimeMs === right.mtimeMs && left.size === right.size
}

async function readSourceFile(sourcePath: string) {
  try {
    return await readFile(sourcePath, 'utf8')
  } catch (error) {
    throw createDiagnostic(
      'SOURCE_READ_FAILED',
      `Failed to read feature flags from ${sourcePath}.`,
      ['Verify that the file is readable by Vite and contains valid UTF-8 JSON.'],
      error,
    )
  }
}

function parseFlagDocument(sourceText: string, sourcePath: string): Record<string, unknown> {
  try {
    const parsed = JSON.parse(sourceText) as unknown
    if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') {
      throw new TypeError('Expected the JSON document root to be an object.')
    }

    return parsed as Record<string, unknown>
  } catch (error) {
    throw createDiagnostic(
      'INVALID_JSON',
      `Feature flags in ${sourcePath} must be a JSON object.`,
      ['Fix the JSON syntax and keep the top-level shape as a flat object of primitive flag values.'],
      error,
    )
  }
}

function pickExposedFlags(
  parsedFlags: Record<string, unknown>,
  exposedKeys: readonly string[],
  sourcePath: string,
): Record<string, FeatureFlagValue> {
  const missingKeys: string[] = []
  const invalidKeys: string[] = []
  const publicFlags: Record<string, FeatureFlagValue> = {}

  for (const key of exposedKeys) {
    if (!(key in parsedFlags)) {
      missingKeys.push(key)
      continue
    }

    const value = parsedFlags[key]
    if (!isFeatureFlagValue(value)) {
      invalidKeys.push(key)
      continue
    }

    publicFlags[key] = value
  }

  if (missingKeys.length > 0) {
    throw createDiagnostic(
      'MISSING_EXPOSED_FLAG',
      `The configured public flags are missing from ${sourcePath}: ${missingKeys.join(', ')}.`,
      ['Add the missing keys to the source JSON or remove them from the `expose` list in your Vite config.'],
    )
  }

  if (invalidKeys.length > 0) {
    throw createDiagnostic(
      'INVALID_FLAG_VALUE',
      `The configured public flags in ${sourcePath} must be primitive JSON values: ${invalidKeys.join(', ')}.`,
      ['Replace each invalid value with a boolean, number, string, or null before exposing it to the client bundle.'],

import type { FeatureFlagValue, FeatureFlags } from '@frontend-architect-eval/feature-flags'
import '@frontend-architect-eval/feature-flags'

declare module '@frontend-architect-eval/feature-flags' {
  interface FeatureFlagsSchema {
    checkoutV2: boolean
    theme: 'dark' | 'light'
  }
}

declare module 'virtual:feature-flags' {
  export type { FeatureFlagValue, FeatureFlags }
  export const flags: FeatureFlags
  export default flags
